return milestones.filter(milestone => {
                if (!milestone.due_date) {
                    // No due date = not expired, keep it
                    return true;
                }

                const dueDate = new Date(milestone.due_date);
                // Keep only milestones that are not expired (due date is in future or today)
                return dueDate >= now;
            })

